const $=s=>document.querySelector(s),main=$('#main');
let lang='en';try{lang=localStorage.getItem('hs-language')==='th'?'th':'en'}catch{}
const t=(en,th)=>lang==='th'?(th||en):en,tx=v=>typeof v==='string'?v:(v?.[lang]||v?.en||'');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let site={appearance:structuredClone(DEFAULT_APPEARANCE),content:structuredClone(DEFAULT_CONTENT),media:[]},etag='',session={role:'visitor',courses:[]},online=false;
let draftAppearance=null,draftContent=null,selectedMedia=null,previewing=false,uploading=false;
const demo={role:null,done:new Set([0,1,2]),lesson:3,attempts:0,score:null,grade:null,feedback:'',homework:'',messages:[],requests:[],registrations:[],assigned:true,child:'Mek'};
const roleName=r=>({admin:t('Administrator','ผู้ดูแลระบบ'),teacher:t('Teacher','ครู'),student:t('Student','นักเรียน'),parent:t('Parent','ผู้ปกครอง'),visitor:t('Visitor','ผู้เยี่ยมชม')})[r];
const courseIds=['science','physics','chemistry'];
const content=id=>({...DEFAULT_CONTENT[id],...site.content[id]});
function button(label,path,style='dark'){return `<a class="button ${style}" href="#${path}">${label} <span>↗</span></a>`}
const empty=(title,body)=>`<div class="empty"><h3>${title}</h3><p>${body}</p></div>`;
const notice=(message,warning=false)=>`<div class="notice ${warning?'warning':''}">${message}</div>`;
function toast(en,th){$('#toast').textContent=t(en,th);$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();$('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView()};
$('.mobile-menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',open)};
function media(id){return site.media.find(m=>m.id===id)}
function picture(id,fallback='',cls=''){const m=media(id);if(!m)return fallback?`<img class="${cls}" src="${fallback}" alt="${esc(t('Illustrative science learning image','ภาพประกอบการเรียนรู้วิทยาศาสตร์'))}">`:'';return `<img class="${cls}" src="/api/media/${m.id}?v=${m.version}" alt="${esc(tx(m.alt))}" style="object-position:${m.focal.x}% ${m.focal.y}%" loading="lazy" decoding="async" ${m.width?`width="${m.width}" height="${m.height}"`:''}>`}
function heading(label,title,body=''){return `<div class="page-intro"><div class="breadcrumb"><a href="#home">${t('Home','หน้าแรก')}</a> / ${label}</div><h1>${title}</h1><p>${body}</p></div>`}
function card(id,learn=false){const c=content(id);return `<article class="card"><a class="course-art ${id==='physics'?'physics':id==='chemistry'?'chem':''} ${c.image?'with-image':''}" href="#${learn?'portal/learn':'course/'+id}" aria-label="${esc(tx(c.title))}">${c.image?picture(c.image):`<span class="formula">${id==='science'?'H₂O':id==='physics'?'F = ma':'Na⁺'}</span><span class="art-caption">HEADSTART / ${c.subject.en.toUpperCase()}</span>`}</a><div class="card-body"><span class="tag">${tx(c.subject)}</span> <span class="tag gray">${tx(c.level)}</span><h3>${esc(tx(c.title))}</h3><p>${esc(tx(c.subtitle))}</p><p class="teaching-language">${t('Teaching language','ภาษาที่ใช้สอน')}: ${languageName(c.language)}</p>${learn?`<progress value="${demo.done.size}" max="8" aria-label="${t('Lesson progress','ความก้าวหน้า')}"></progress><p>${demo.done.size}/8 ${t('lessons complete','บทเรียนที่เสร็จแล้ว')}</p>`:''}<div class="card-foot"><span>${c.lessons} ${t('sample lessons','บทเรียนตัวอย่าง')} · ${c.age}</span><a href="#${learn?'portal/learn':'course/'+id}">${t(learn?'Continue':'Explore',learn?'เรียนต่อ':'ดูหลักสูตร')} ↗</a></div></div></article>`}
function languageName(code){return code==='en'?t('English','อังกฤษ'):code==='both'?t('English & Thai','อังกฤษและไทย'):t('Thai','ไทย')}
function home(){const c=content('home');return `<div class="container"><section class="hero"><div><div class="eyebrow">${t('A HEAD START FOR A BRIGHTER FUTURE','ก้าวแรกของอนาคตที่สดใส')}</div><h1>${esc(tx(c.title)).replace(/\n/g,'<br>')}</h1><p>${esc(tx(c.description))}</p><div class="actions">${button(t('Find your course','ค้นหาหลักสูตรที่ใช่'),'courses')}${button(t('Try a lesson','ทดลองเรียน'),'resources','')}</div><div class="hero-meta">✓ ${t('Learn at your pace','เรียนรู้ตามจังหวะของตัวเอง')} &nbsp; ✓ ${t('Understand, not just memorise','เข้าใจมากกว่าท่องจำ')}</div></div><div class="hero-media">${picture(c.image,'hero.png')}<div class="floating-note"><b>✧</b><div><strong>${t('Curiosity starts here.','ความสงสัยเริ่มต้นที่นี่')}</strong><small>${t('Every question is a step forward.','ทุกคำถามพาเราไปได้ไกลขึ้น')}</small></div></div><span class="image-label">${c.image?esc(tx(media(c.image)?.caption)):t('AI illustration • not a school photograph','ภาพประกอบ AI ไม่ใช่ภาพของโรงเรียน')}</span></div></section><div class="principles">${[[t('Understand deeply','เข้าใจอย่างลึกซึ้ง'),t('Build strong foundations','สร้างพื้นฐานที่แข็งแรง')],[t('Learn by exploring','เรียนรู้ผ่านการลงมือ'),t('Connect ideas to life','เชื่อมความคิดกับชีวิตจริง')],[t('Grow with confidence','เติบโตอย่างมั่นใจ'),t('One discovery at a time','ผ่านการค้นพบทีละก้าว')]].map(([a,b],i)=>`<div><b>0${i+1}</b><span>${a}<small>${b}</small></span></div>`).join('')}</div><section class="section"><div class="heading-row"><div><div class="eyebrow">${t('FIND YOUR NEXT DISCOVERY','ค้นพบสิ่งใหม่ในการเรียนรู้')}</div><h2>${t('A learning path for every curious mind','เส้นทางการเรียนรู้สำหรับทุกความสงสัย')}</h2><p>${t('Sample courses, from upper primary to secondary school.','หลักสูตรตัวอย่าง ตั้งแต่ประถมปลายถึงมัธยมปลาย')}</p></div><a class="text-link" href="#courses">${t('All courses','หลักสูตรทั้งหมด')} ↗</a></div><div class="grid">${courseIds.map(id=>card(id)).join('')}</div></section></div><section class="section light"><div class="container split"><div class="feature-box"><div class="eyebrow" style="color:var(--green)">HEADSTART ACADEMICS</div><h2>${esc(tx(content('about').title))}</h2><p>${esc(tx(content('about').description))}</p>${button(t('Get to know us','รู้จักเรา'),'about','green')}</div><ol class="number-list">${[[t('See the idea before the formula','มองเห็นภาพก่อนจำสูตร'),t('Start with real-world questions.','เริ่มจากคำถามในโลกจริง')],[t('Explore. Try. Reflect.','สำรวจ ทดลอง ทบทวน'),t('Make room for experiments and practice.','เรียนรู้ผ่านการทดลองและฝึกฝน')],[t('See progress together','มองเห็นพัฒนาการไปด้วยกัน'),t('Students, teachers, and parents share the journey.','นักเรียน ครู และผู้ปกครองร่วมเดินทางไปด้วยกัน')]].map(([a,b],i)=>`<li><b>0${i+1}/</b><div><h3>${a}</h3><p>${b}</p></div></li>`).join('')}</ol></div></section><div class="container"><section class="section"><div class="heading-row"><h2>${t('Learning beyond the lesson','เรียนรู้นอกเหนือบทเรียน')}</h2><a class="text-link" href="#resources">${t('Explore free resources','สำรวจแหล่งเรียนรู้ฟรี')} ↗</a></div><div class="grid"><article class="card card-body"><span class="tag">Science in Life</span><h3>${esc(tx(content('article').title))}</h3>${button(t('Read the article','อ่านบทความ'),'article','')}</article><article class="card card-body"><span class="tag">${t('Interactive lab','ห้องทดลองจำลอง')}</span><h3>${t('Forces, mass & acceleration','แรง มวล และความเร่ง')}</h3>${button(t('Explore the lab','เข้าห้องทดลอง'),'lab','')}</article><article class="card card-body"><span class="tag">${t('Meet your teachers','รู้จักทีมผู้สอน')}</span><h3>Dr. Toey</h3><p>${esc(tx(content('teacher').description))}</p><a class="text-link" href="#about">${t('Our teaching team','ทีมผู้สอนของเรา')} ↗</a></article></div></section><h2>${t('Discover something together','ค้นพบสิ่งใหม่ไปด้วยกัน')}</h2>${eventRow()}<div class="cta" style="margin-top:50px"><div><h2>${t('Your next chapter begins here.','ก้าวต่อไปเริ่มต้นที่นี่')}</h2><p>${t('Explore a course. Follow your curiosity.','สำรวจหลักสูตรและค้นหาสิ่งที่อยากเรียนรู้')}</p></div>${button(t('Explore courses','สำรวจหลักสูตร'),'courses')}</div></div>`}
function about(){return `<div class="container">${heading(t('About us','รู้จักเรา'),esc(tx(content('about').title)),esc(tx(content('about').description)))}<div class="grid">${['teacher','gallery'].map(id=>`<article class="card card-body">${picture(content(id).image,'','content-image')}<h2>${esc(tx(content(id).title))}</h2><p>${esc(tx(content(id).description))}</p></article>`).join('')}<article class="card card-body"><h2>${t('School profile','ข้อมูลโรงเรียน')}</h2><p>${t('School history, verified qualifications, and achievements are awaiting school approval.','ประวัติโรงเรียน คุณวุฒิ และผลงานที่ยืนยันแล้วรอโรงเรียนอนุมัติ')}</p></article></div><section class="section"><h2>${t('Student & parent voices','เสียงจากนักเรียนและผู้ปกครอง')}</h2>${empty(t('No approved reviews yet','ยังไม่มีรีวิวที่อนุมัติ'),t('Only verified reviews with permission will be published.','เผยแพร่เฉพาะรีวิวที่ตรวจสอบและได้รับความยินยอม'))}<h2>${t('Learning materials','สื่อการเรียนรู้')}</h2><p>Lab and Learn · Stick and Learn</p><p>${t('School-approved product descriptions and images are pending.','รอรายละเอียดและภาพสื่อที่โรงเรียนอนุมัติ')}</p></section></div>`}
function catalog(){return `<div class="container">${heading(t('Courses','หลักสูตร'),t('Find your next discovery','ค้นพบหลักสูตรที่ใช่'),t('Sample course information • subject to school approval.','ข้อมูลหลักสูตรตัวอย่าง รอโรงเรียนอนุมัติ'))}<div class="filters"><input id="search" aria-label="${t('Search courses','ค้นหาหลักสูตร')}" placeholder="${t('Search courses…','ค้นหาหลักสูตร…')}"><select id="subject" aria-label="${t('Subject','วิชา')}"><option value="">${t('All subjects','ทุกวิชา')}</option>${courseIds.map(id=>`<option value="${id}">${tx(content(id).subject)}</option>`).join('')}</select><select id="level" aria-label="${t('Level','ระดับชั้น')}"><option value="">${t('All levels','ทุกระดับชั้น')}</option>${courseIds.map(id=>`<option value="${id}">${tx(content(id).level)}</option>`).join('')}</select></div><p id="result-count" aria-live="polite"></p><div class="grid" id="course-results">${courseIds.map(id=>card(id)).join('')}</div>${notice(t('Enrollment requests do not grant course access. An administrator must assign access after review.','คำขอเรียนไม่ให้สิทธิ์เข้าถึงหลักสูตร ผู้ดูแลต้องตรวจสอบและมอบหมายสิทธิ์'))}<div style="height:40px"></div></div>`}
function course(id){if(!courseIds.includes(id))return notFound();const c=content(id);return `<div class="container">${heading(t('Courses','หลักสูตร'),esc(tx(c.title)),esc(tx(c.subtitle)))}<div class="detail-top"><div><p>${esc(tx(c.description))}</p><h3>${t('Who is this for?','เหมาะสำหรับใคร')}</h3><p>${tx(c.level)} · ${t('Ages','อายุ')} ${c.age}</p><p>${t('Recommended preparation: reading and problem-solving at the indicated school level.','พื้นฐานที่แนะนำ: การอ่านและแก้ปัญหาตามระดับชั้นที่ระบุ')}</p><h3>${t('What you will learn','สิ่งที่จะได้เรียนรู้')}</h3><ul><li>${t('Observe, ask questions, and explain ideas.','สังเกต ตั้งคำถาม และอธิบายแนวคิด')}</li><li>${t('Connect scientific ideas to everyday situations.','เชื่อมแนวคิดวิทยาศาสตร์กับชีวิตประจำวัน')}</li><li>${t('Reflect through practice and assessment.','ทบทวนผ่านการฝึกฝนและแบบทดสอบ')}</li></ul>${[t('Foundations','พื้นฐาน'),t('Explore and apply','สำรวจและนำไปใช้'),t('Practice and review','ฝึกฝนและทบทวน')].map((m,i)=>`<details><summary>${i+1}. ${m}</summary><p>${t('Sample syllabus. Approved lessons and materials are pending.','โครงสร้างตัวอย่าง รอบทเรียนและเอกสารที่อนุมัติ')}</p></details>`).join('')}</div><aside class="sticky-card">${picture(c.image,'','content-image')}<h3>${t('Course information','ข้อมูลหลักสูตร')}</h3><p>${t('Teacher: to be assigned','ผู้สอน: รอกำหนด')}<br>${c.lessons} ${t('sample lessons','บทเรียนตัวอย่าง')}<br>${t('Video duration: pending','ความยาววิดีโอ: รอข้อมูล')}<br>${t('Sample access: 90 days from assignment','สิทธิ์ตัวอย่าง: 90 วันจากการมอบหมาย')}</p><strong>${t('Teaching language','ภาษาที่ใช้สอน')}: ${languageName(c.language)}</strong>${notice(t('Changing the interface language does not translate videos or uploaded documents.','การเปลี่ยนภาษาเมนูไม่ได้แปลวิดีโอหรือเอกสารที่อัปโหลด'))}<button class="primary" data-enroll="${id}">${t('Request enrollment (demo)','ส่งคำขอเรียน (สาธิต)')}</button></aside></div><div class="section">${button(t('Try a lesson','ทดลองเรียน'),'resources','')}</div></div>`}
function resources(){return `<div class="container">${heading(t('Free resources','เรียนรู้ฟรี'),t('A little curiosity goes a long way.','ความสงสัยพาเราไปได้ไกล'),t('Explore science, learning strategies, and practice.','สำรวจวิทยาศาสตร์ กลยุทธ์การเรียน และการฝึกฝน'))}<div class="grid">${[[t('Science Simplified','วิทยาศาสตร์เข้าใจง่าย'),tx(content('article').title),'article'],[t('Study Smarter','เรียนอย่างมีวิธี'),t('Explain it in your own words','อธิบายด้วยคำของตัวเอง'),'article/study'],[t('Exam Excellence','เตรียมสอบอย่างมั่นใจ'),t('Break a problem into steps','แบ่งโจทย์เป็นขั้นตอน'),'article/exam']].map(([tag,title,url])=>`<article class="card card-body"><span class="tag">${tag}</span><h3>${esc(title)}</h3>${button(t('Read more','อ่านต่อ'),url,'')}</article>`).join('')}</div><section class="section"><h2>${t('Trial video lessons','วิดีโอบทเรียนทดลอง')}</h2>${empty(t('Approved videos are not available yet','ยังไม่มีวิดีโอที่อนุมัติ'),t('Only videos the school has permission to publish will appear here.','แสดงเฉพาะวิดีโอที่โรงเรียนมีสิทธิ์เผยแพร่'))}<div class="panel"><h2>${t('Forces, mass & acceleration','แรง มวล และความเร่ง')}</h2><p>${t('Explore F = ma in an isolated interactive lab.','สำรวจ F = ma ในห้องทดลองที่แยกจากระบบหลัก')}</p>${button(t('Open the lab','เปิดห้องทดลอง'),'lab')}</div></section></div>`}
function article(id){return `<div class="container narrow">${heading(t('Free resources','เรียนรู้ฟรี'),id==='study'?t('Explain it in your own words','อธิบายด้วยคำของตัวเอง'):id==='exam'?t('Break a problem into steps','แบ่งโจทย์เป็นขั้นตอน'):esc(tx(content('article').title)))}<div class="panel">${!id?picture(content('article').image,'','content-image'):''}<p>${id==='study'?t('Close your notes and describe what you learned. Check uncertain points, then return to them later. What can you explain? What questions remain?','ปิดสมุดแล้วอธิบายสิ่งที่เรียน ตรวจส่วนที่ไม่แน่ใจและกลับมาทบทวนภายหลัง คุณอธิบายอะไรได้แล้ว และยังมีคำถามอะไร?'):id==='exam'?t('Identify what the question gives you and what you need to find. Keep track of units. After solving, check whether your answer makes sense.','ระบุข้อมูลที่โจทย์ให้และสิ่งที่ต้องหา เขียนหน่วยกำกับ แล้วตรวจว่าคำตอบสอดคล้องกับสถานการณ์หรือไม่'):esc(tx(content('article').description))}</p>${notice(t('Sample educational content; school review pending.','เนื้อหาการศึกษาตัวอย่าง รอโรงเรียนตรวจทาน'))}</div></div>`}
function lab(){const doc=`<!doctype html><html lang="${lang}"><meta charset="utf-8"><style>body{font:16px system-ui;color:#152238;background:#f1f5e8;padding:20px}label{display:block;margin:18px 0}input{width:70%}output{font-size:28px}h2{margin:0}</style><h2>F = ma</h2><label>${t('Force','แรง')} F: <b id="fv">10</b> N<br><input aria-label="${t('Force','แรง')}" id="f" type="range" min="0" max="50" value="10"></label><label>${t('Mass','มวล')} m: <b id="mv">2</b> kg<br><input aria-label="${t('Mass','มวล')}" id="m" type="range" min="1" max="10" value="2"></label><p>${t('Acceleration','ความเร่ง')} a = <output id="a">5.00</output> m/s²</p><script>function update(){fv.textContent=f.value;mv.textContent=m.value;a.textContent=(f.value/m.value).toFixed(2)}f.oninput=m.oninput=update;<\/script></html>`;return `<div class="container narrow">${heading(t('Interactive lab','ห้องทดลองจำลอง'),t('Explore force and motion','สำรวจแรงและการเคลื่อนที่'))}<iframe class="lab" title="${t('Force and mass experiment','การทดลองแรงและมวล')}" sandbox="allow-scripts" srcdoc="${esc(doc)}"></iframe><p>${t('Model assumptions: the applied force is the net force; mass is constant over time.','สมมติฐาน: แรงที่กำหนดเป็นแรงลัพธ์ มวลคงที่ตลอดเวลา')}</p></div>`}
function eventRow(){const e=content('event'),count=6+demo.registrations.filter(r=>!r.cancelled).length;return `<article class="event-row"><div class="date-box"><b>17</b>${t('OCT 2026','ต.ค. 2569')}</div><div><span class="tag">${t('Free workshop · sample event','เวิร์กช็อปฟรี · กิจกรรมตัวอย่าง')}</span><h3>${esc(tx(e.title))}</h3><p>${t('09:00–12:00 · in person','09:00–12:00 น. · ณ สถานที่จริง')}</p><p>${count}/12 ${t('places filled','ที่นั่ง')}</p></div><button class="button dark" data-event ${count>=12?'disabled':''}>${count>=12?t('Full','เต็มแล้ว'):t('View event','ดูกิจกรรม')} ↗</button></article>`}
function eventsPage(){return `<div class="container">${heading(t('Events','กิจกรรม'),t('Discover something together','ค้นพบสิ่งใหม่ไปด้วยกัน'),t('In-person workshops and free sessions. No live online classes.','เวิร์กช็อปและกิจกรรม ณ สถานที่จริง ไม่มีการสอนออนไลน์สด'))}${picture(content('event').image,'','event-image')}<p>${esc(tx(content('event').description))}</p>${eventRow()}${notice(t('Dates, capacity, and registration are illustrative. No real booking is made.','วันเวลา จำนวนที่นั่ง และการลงทะเบียนเป็นตัวอย่าง ไม่มีการจองจริง'),true)}</div>`}
function contact(){return `<div class="container">${heading(t('Contact','ติดต่อเรา'),t('Let’s find your learning path.','มาค้นหาเส้นทางการเรียนรู้ด้วยกัน'))}<div class="split"><div class="panel"><h2>Headstart Academics</h2><p>${t('School address, email, telephone, and LINE OA details are awaiting verification.','ที่อยู่ อีเมล โทรศัพท์ และ LINE OA รอการยืนยันจากโรงเรียน')}</p></div><div class="panel"><h2>${t('Leave a sample enquiry','ฝากคำถามตัวอย่าง')}</h2><form id="contact-form"><label>${t('Name (fictional only)','ชื่อ (ใช้ชื่อสมมติ)')}<input required maxlength="80"></label><label>${t('Question','คำถาม')}<textarea required maxlength="1000"></textarea></label><button class="primary">${t('Check sample form','ตรวจสอบแบบฟอร์มตัวอย่าง')}</button></form><p>${t('No message will be sent.','ไม่มีการส่งข้อความจริง')}</p></div></div></div>`}
function login(){return `<div class="container narrow">${heading(t('My learning','พื้นที่การเรียนรู้'),t('Welcome to your learning space','ยินดีต้อนรับสู่พื้นที่การเรียนรู้'))}<div class="auth-box"><h2>${t('Website management','การจัดการเว็บไซต์')}</h2>${session.role==='admin'?button(t('Open website settings','เปิดการตั้งค่าเว็บไซต์'),'portal/appearance'):session.role==='teacher'?button(t('Manage course media','จัดการสื่อหลักสูตร'),'portal/media'):online?`<a class="button dark" href="/signin-with-chatgpt?return_to=%2F%23portal%2Fappearance" target="_top">${t('Sign in with ChatGPT','เข้าสู่ระบบด้วย ChatGPT')}</a>`:notice(t('Local preview: server authentication and shared storage are unavailable here.','ตัวอย่างในเครื่อง: ยังไม่เชื่อมต่อการยืนยันตัวตนและที่เก็บข้อมูลส่วนกลาง'),true)}<p>${t('Only authorized administrators can publish branding or manage public media.','เฉพาะผู้ดูแลที่ได้รับอนุญาตเท่านั้นที่เผยแพร่แบรนด์หรือจัดการสื่อสาธารณะได้')}</p><hr><h3>${t('Explore the LMS prototype','ทดลองใช้ต้นแบบระบบการเรียน')}</h3><p>${t('Demo roles do not grant administrative permission. Never enter real student data.','บทบาทสาธิตไม่ให้สิทธิ์ผู้ดูแลจริง ห้ามกรอกข้อมูลนักเรียนจริง')}</p><div class="role-options">${['student','parent','teacher','admin'].map(r=>`<button data-role="${r}">${roleName(r)} ↗</button>`).join('')}</div><div class="inline-actions"><a class="text-link" href="#register">${t('Registration form','แบบฟอร์มสมัครสมาชิก')}</a><a class="text-link" href="#reset">${t('Password reset','รีเซ็ตรหัสผ่าน')}</a></div></div></div>`}
function register(){return `<div class="container narrow">${heading(t('Register','สมัครสมาชิก'),t('Start your learning journey','เริ่มต้นเส้นทางการเรียนรู้'),t('Sample form only. No account is created.','แบบฟอร์มตัวอย่างเท่านั้น ไม่มีการสร้างบัญชี'))}<div class="auth-box"><form id="register-form"><label>${t('Account role','ประเภทบัญชี')}<select name="role" id="reg-role"><option value="student">${roleName('student')}</option><option value="parent">${roleName('parent')}</option></select></label><div class="two">${field('first',t('First name','ชื่อ'))}${field('last',t('Last name','นามสกุล'))}</div>${field('email',t('Email','อีเมล'),'','email')}${field('phone',t('Phone','โทรศัพท์'))}<div id="student-fields">${field('age',t('Age','อายุ'),'','number')}${field('parentEmail',t('Parent email','อีเมลผู้ปกครอง'),'','email')}${field('school',t('School','โรงเรียน'))}<label>${t('School level','ระดับชั้น')}<select name="level">${courseIds.map(id=>`<option>${tx(content(id).level)}</option>`).join('')}</select></label></div>${field('other',t('Other contact (optional)','ช่องทางติดต่ออื่น (ไม่บังคับ)'),'','text',false)}<p>${t('Parent relationships require a verified invitation or administrator approval.','ความสัมพันธ์ผู้ปกครองต้องยืนยันด้วยคำเชิญหรือผู้ดูแลอนุมัติ')}</p><button class="primary">${t('Check sample registration','ตรวจสอบการสมัครตัวอย่าง')}</button></form></div></div>`}
function field(name,label,value='',type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="200" ${type==='number'?'min="5" max="99"':''}></label>`}
function notFound(){return empty(t('Page not found','ไม่พบหน้านี้'),t('Choose a page from the navigation.','เลือกหน้าจากเมนูนำทาง'))}
function stats(values){return `<div class="stats">${values.map(([v,l])=>`<div class="stat"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>`}
function portal(page='overview'){const r=demo.role||session.role;if(!['admin','teacher','student','parent'].includes(r))return login();const menus=r==='admin'?[['overview',t('School overview','ภาพรวมโรงเรียน')],['users',t('Users & access','ผู้ใช้และสิทธิ์')],['manage',t('Courses','หลักสูตร')],['eventadmin',t('Registrations','การลงทะเบียน')],['content',t('Bilingual content','เนื้อหาสองภาษา')],['appearance',t('Website appearance','รูปลักษณ์เว็บไซต์')],['media',t('Media library','คลังสื่อ')]]:r==='teacher'?[['overview',t('Teaching overview','ภาพรวมการสอน')],['grading',t('Grading','ตรวจงาน')],['reports',t('Parent reports','รายงานผู้ปกครอง')],['messages',t('Messages','ข้อความ')],['media',t('Course media','สื่อหลักสูตร')]]:r==='student'?[['overview',t('Learning overview','ภาพรวมการเรียน')],['learn',t('My courses','หลักสูตรของฉัน')],['assess',t('Assessments','แบบทดสอบ')],['messages',t('Questions','คำถาม')],['certificates',t('Certificates','ใบประกาศ')]]:[['overview',t('Children’s progress','พัฒนาการบุตรหลาน')],['reports',t('Results & feedback','ผลและข้อเสนอแนะ')],['messages',t('Messages','ข้อความ')]];const allowed=menus.some(m=>m[0]===page);return `<div class="portal"><aside class="sidebar"><div class="profile"><b>${roleName(r)}</b><small>${demo.role?t('Demo role','บทบาทสาธิต'):t('Verified account','บัญชีที่ยืนยันแล้ว')}</small></div>${menus.map(([id,title])=>`<a class="${page===id?'active':''}" href="#portal/${id}">${title}</a>`).join('')}<a href="#login" data-exit>${t('Switch demo role','เปลี่ยนบทบาทสาธิต')} ↗</a>${online&&session.role!=='visitor'?`<a href="/signout-with-chatgpt?return_to=%2F" target="_top">${t('Sign out','ออกจากระบบ')}</a>`:''}</aside><div class="portal-content"><div class="heading-row"><div><div class="eyebrow">MY HEADSTART</div><h1>${menus.find(m=>m[0]===page)?.[1]||t('Access restricted','จำกัดการเข้าถึง')}</h1></div><span class="tag gray">${demo.role?t('LMS demo','สาธิตระบบการเรียน'):t('Website management','จัดการเว็บไซต์')}</span></div>${!['appearance','media','content'].includes(page)?notice(t('LMS sample data resets when you reload. Role switching does not change your server permissions.','ข้อมูลสาธิตระบบการเรียนรีเซ็ตเมื่อโหลดใหม่ การเปลี่ยนบทบาทไม่เปลี่ยนสิทธิ์บนเซิร์ฟเวอร์')):''}${allowed?portalBody(page,r):notFound()}</div></div>`}
function portalBody(page,r){if(page==='appearance')return appearancePage();if(page==='media')return mediaPage();if(page==='content'||page==='manage')return editorPage();if(page==='learn')return learnPage();if(page==='assess')return assessmentPage();if(page==='messages')return messagesPage();if(page==='grading')return gradingPage();if(page==='reports')return reportsPage(r);if(page==='users')return `<div class="panel"><h2>${t('Course assignment','สิทธิ์หลักสูตร')}</h2><p>Mek · Science Explorer · ${demo.assigned?t('Assigned','มอบหมายแล้ว'):t('Revoked','เพิกถอนแล้ว')}</p><button class="primary" id="access-toggle">${demo.assigned?t('Revoke demo access','เพิกถอนสิทธิ์สาธิต'):t('Assign demo access','มอบหมายสิทธิ์สาธิต')}</button><h3 style="margin-top:30px">${t('Enrollment requests','คำขอเรียน')}</h3><p>${demo.requests.map(id=>esc(tx(content(id).title))).join(', ')||t('No requests yet.','ยังไม่มีคำขอ')}</p><h3>${t('Verified guardian links','ความสัมพันธ์ผู้ปกครองที่ยืนยันแล้ว')}</h3><p>${t('Sample parent linked to Mek and Fah. Real invitations and account management are not connected.','ผู้ปกครองตัวอย่างเชื่อมกับเมฆและฟ้า คำเชิญและการจัดการบัญชีจริงยังไม่เชื่อมต่อ')}</p></div>`;if(page==='eventadmin')return `<div class="panel"><h2>${t('Workshop registrations','การลงทะเบียนเวิร์กช็อป')}</h2>${demo.registrations.map((v,i)=>`<div class="message">DEMO-${i+1} · ${v.cancelled?t('Cancelled','ยกเลิกแล้ว'):t('Registered in demo','ลงทะเบียนสาธิตแล้ว')} <button data-cancel="${i}" class="button small" ${v.cancelled?'disabled':''}>${t('Cancel','ยกเลิก')}</button></div>`).join('')||empty(t('No new registrations','ยังไม่มีการลงทะเบียนใหม่'),t('Try a sample event registration.','ลองลงทะเบียนกิจกรรมตัวอย่าง'))}</div>`;if(page==='certificates')return empty(demo.done.size===8&&demo.score>=60?t('Sample completion criteria met','ผ่านเกณฑ์สำเร็จตัวอย่าง'):t('No certificates yet','ยังไม่มีใบประกาศ'),t('Complete all 8 lessons and score at least 60%. Real certificate issuance is not connected.','เรียนครบ 8 บทและสอบอย่างน้อย 60% ยังไม่เชื่อมต่อการออกใบประกาศจริง'));
if(r==='parent')return `<label>${t('Verified linked child','บุตรหลานที่ยืนยันความสัมพันธ์')}<select id="child"><option value="Mek" ${demo.child==='Mek'?'selected':''}>${t('Mek','เมฆ')}</option><option value="Fah" ${demo.child==='Fah'?'selected':''}>${t('Fah','ฟ้า')}</option></select></label>${demo.child==='Fah'?empty(t('No courses assigned','ยังไม่มีหลักสูตร'),t('An administrator must assign a course first.','ผู้ดูแลต้องมอบหมายหลักสูตรก่อน')):summary()+reportsPage(r)}`;
if(r==='student')return `${summary()}<div class="grid">${demo.assigned?card('science',true):empty(t('No assigned courses','ยังไม่มีหลักสูตรที่มอบหมาย'),t('Wait for administrator review.','รอผู้ดูแลตรวจสอบ'))}<div class="card card-body"><span class="tag">${t('Next step','ขั้นตอนต่อไป')}</span><h3>${t('Observe the world around you','สังเกตโลกรอบตัว')}</h3><p>${t('Sample assignment due 30 October 2026.','งานตัวอย่างกำหนดส่ง 30 ตุลาคม 2569')}</p>${button(t('View assignment','ดูงาน'),'portal/assess','')}</div></div>`;
return `${stats([[1,t('Sample student','นักเรียนตัวอย่าง')],[demo.assigned?1:0,t('Assigned courses','หลักสูตรที่มอบหมาย')],[demo.done.size+'/8',t('Completed lessons','บทเรียนที่เสร็จแล้ว')],[demo.grade===null?1:0,t('Pending grading','งานรอตรวจ')]])}<div class="grid"><div class="panel"><h3>Science Explorer</h3><p>${t('Mek','เมฆ')} · ${Math.round(demo.done.size/8*100)}%</p><progress value="${demo.done.size}" max="8"></progress></div><div class="panel"><h3>${t('Your next action','งานถัดไป')}</h3>${button(r==='admin'?t('Manage website','จัดการเว็บไซต์'):t('Review assignment','ตรวจงาน'),r==='admin'?'portal/appearance':'portal/grading')}</div></div>`}
function summary(){return stats([[demo.assigned?1:0,t('Assigned courses','หลักสูตรที่มอบหมาย')],[demo.done.size+'/8',t('Lessons complete','บทเรียนที่เสร็จ')],[demo.score===null?'—':demo.score+'%',t('Assessment result','ผลแบบทดสอบ')],[demo.grade===null?'—':demo.grade+'/10',t('Assignment grade','คะแนนงาน')]])}
function learnPage(){if(!demo.assigned)return empty(t('Access has been revoked','สิทธิ์ถูกเพิกถอน'),t('Ask an administrator to review your assignment.','ติดต่อผู้ดูแลเพื่อตรวจสอบสิทธิ์'));return `<div class="learning"><div><div class="video-empty"><span class="play-icon">▷</span><h3>${esc(tx(content('lesson').title))}</h3><p>${t('Approved prerecorded video not yet available.','ยังไม่มีวิดีโอที่บันทึกไว้และได้รับอนุมัติ')}</p></div><div class="panel"><h2>${esc(tx(content('lesson').title))}</h2><p>${esc(tx(content('lesson').description))}</p>${picture(content('lesson').image,'','content-image')}<p>${t('Teaching language','ภาษาที่ใช้สอน')}: ${languageName(content('science').language)}</p>${notice(t('Interface translation does not translate video or document content.','การแปลเมนูไม่ได้แปลวิดีโอหรือเนื้อหาเอกสาร'))}<button id="complete" class="primary">${demo.done.has(demo.lesson)?t('Undo sample completion','ยกเลิกสถานะเรียนจบตัวอย่าง'):t('Mark complete (demo)','ทำเครื่องหมายเรียนจบ (สาธิต)')}</button><div class="actions">${button(t('Assignment & quiz','งานและแบบทดสอบ'),'portal/assess','')}</div></div></div><aside><h3>${t('Course lessons','บทเรียนในหลักสูตร')}</h3>${Array.from({length:8},(_,i)=>`<button class="lesson-row ${demo.lesson===i?'active':''}" data-lesson="${i}">${demo.done.has(i)?'✓':'○'} ${t('Lesson','บทที่')} ${i+1}<small>${t('Video pending approval','วิดีโอรอการอนุมัติ')}</small></button>`).join('')}</aside></div>`}
function assessmentPage(){return `<div class="panel"><h2>${t('Forces & motion: sample quiz','แรงและการเคลื่อนที่: แบบทดสอบตัวอย่าง')}</h2><p>${t('Pass: 60% · Attempts:','ผ่าน: 60% · จำนวนครั้ง:')} ${demo.attempts}/2</p>${demo.score!==null?notice(t('Latest score: ','คะแนนล่าสุด: ')+demo.score+'%'):''}<form id="quiz"><fieldset><legend>${t('With constant force, doubling mass makes acceleration…','เมื่อแรงคงที่ การเพิ่มมวลเป็นสองเท่าทำให้ความเร่ง…')}</legend>${[t('Twice as large','เพิ่มเป็นสองเท่า'),t('Half as large','ลดลงครึ่งหนึ่ง'),t('Unchanged','เท่าเดิม')].map((s,i)=>`<label class="question-option"><input required type="radio" name="q1" value="${i}">${s}</label>`).join('')}</fieldset><fieldset><legend>${t('What is the SI unit of force?','หน่วย SI ของแรงคืออะไร?')}</legend>${[t('Newton','นิวตัน'),t('Kilogram','กิโลกรัม'),t('Metre','เมตร')].map((s,i)=>`<label class="question-option"><input required type="radio" name="q2" value="${i}">${s}</label>`).join('')}</fieldset><button class="primary" ${demo.attempts>=2?'disabled':''}>${demo.attempts>=2?t('Attempt limit reached','ครบจำนวนครั้งแล้ว'):t('Submit sample answers','ส่งคำตอบตัวอย่าง')}</button></form><p>${t('Demo scoring runs in your browser. Do not use for real exams. Answer review is disabled.','คะแนนสาธิตคำนวณในเบราว์เซอร์ ห้ามใช้สอบจริง ปิดการแสดงเฉลย')}</p></div><div class="panel"><h2>${t('Written assignment','งานเขียน')}</h2><form id="homework"><label>${t('Your response','คำตอบ')}<textarea required maxlength="2000" name="answer">${esc(demo.homework)}</textarea></label><label>${t('PDF, JPEG, PNG · maximum 5 MB · local check only','PDF, JPEG, PNG · ไม่เกิน 5 MB · ตรวจในเครื่องเท่านั้น')}<input type="file" accept=".pdf,.jpg,.jpeg,.png" id="homework-file"></label><button class="primary">${t('Save demo response','บันทึกคำตอบสาธิต')}</button></form></div>`}
function gradingPage(){return `<div class="panel"><h2>${t('Mek · observation assignment','เมฆ · งานสังเกตสิ่งรอบตัว')}</h2><p>${esc(demo.homework)||t('Sample answer: I wonder why ice floats. I would compare mass and volume.','คำตอบตัวอย่าง: ฉันสงสัยว่าทำไมน้ำแข็งลอยได้ จึงอยากเปรียบเทียบมวลและปริมาตร')}</p><form id="grading"><label>${t('Score (0–10)','คะแนน (0–10)')}<input type="number" min="0" max="10" step="0.5" required name="grade" value="${demo.grade??''}"></label><label>${t('Feedback','ข้อเสนอแนะ')}<textarea required name="feedback" maxlength="1000">${esc(demo.feedback)}</textarea></label><button class="primary">${t('Save demo grade','บันทึกคะแนนสาธิต')}</button></form></div>`}
function reportsPage(r){return `<div class="panel"><h2>${t('Learning summary','สรุปการเรียนรู้')} · ${t('Mek','เมฆ')}</h2><p>${demo.done.size}/8 ${t('lessons completed, not classroom attendance.','บทเรียนที่เสร็จ ไม่ใช่การเช็กชื่อเข้าเรียน')}</p><p>${t('Quiz score','คะแนนแบบทดสอบ')}: ${demo.score??'—'}</p><p>${t('Teacher feedback','ข้อเสนอแนะครู')}: ${esc(demo.feedback)||t('No feedback yet.','ยังไม่มีข้อเสนอแนะ')}</p>${r==='teacher'?`<form id="report"><label>${t('Review and add a comment','ตรวจทานและเพิ่มความเห็น')}<textarea name="comment" required maxlength="1000">${esc(demo.report||'')}</textarea></label><button class="primary">${t('Save demo draft','บันทึกร่างสาธิต')}</button></form>${notice(t('Email and LINE are not connected. No report is sent.','ยังไม่เชื่อมต่ออีเมลและ LINE ไม่มีการส่งรายงาน'))}`:`<p>${esc(demo.report||'')}</p>`}</div>`}
function messagesPage(){return `<div class="panel"><h2>${t('Course questions & parent messages','คำถามในหลักสูตรและข้อความผู้ปกครอง')}</h2>${demo.messages.map((m,i)=>`<div class="message"><b>${roleName(m.role)}</b><p>${esc(m.text)}</p>${demo.role==='teacher'?`<button class="button small" data-hide="${i}">${t('Hide (demo)','ซ่อน (สาธิต)')}</button>`:''}</div>`).join('')||empty(t('No messages yet','ยังไม่มีข้อความ'),t('Use fictional content only.','ใช้เนื้อหาสมมติเท่านั้น'))}<form id="message"><label>${t('Message','ข้อความ')}<textarea required name="text" maxlength="1000"></textarea></label><button class="primary">${t('Add demo message','เพิ่มข้อความสาธิต')}</button></form></div>`}
function adminGate(){return session.role==='admin'?notice(t('Verified administrator. Saved changes are stored on the server and shared across devices.','ผู้ดูแลที่ยืนยันแล้ว ข้อมูลที่บันทึกเก็บบนเซิร์ฟเวอร์และใช้ร่วมกันข้ามอุปกรณ์')):notice(t('Read-only management preview. Sign in with an authorized administrator account to save or publish. A demo role cannot grant permission.','ตัวอย่างหน้าจัดการแบบอ่านอย่างเดียว เข้าสู่ระบบด้วยบัญชีผู้ดูแลที่ได้รับอนุญาตเพื่อบันทึกหรือเผยแพร่ บทบาทสาธิตไม่ให้สิทธิ์จริง'),true)}
function contrast(a,b){const lum=c=>{const rgb=c.match(/[a-f\d]{2}/gi).map(x=>parseInt(x,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722};const x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
function brandWarnings(a){return [[a.text,a.background,t('Text / background','ข้อความ / พื้นหลัง')],[a.secondary,a.background,t('Secondary / background','สีรอง / พื้นหลัง')],[a.primary,a.accent,t('Primary / accent','สีหลัก / สีเน้น')]].filter(([f,b])=>contrast(f,b)<4.5).map(([f,b,n])=>`${n}: ${contrast(f,b).toFixed(2)}:1`)}
function appearancePage(){draftAppearance??=structuredClone(site.draftAppearance||site.appearance);const a=draftAppearance;return `${adminGate()}<div class="panel"><h2>${t('Your school, your identity','เอกลักษณ์ของโรงเรียน')}</h2><p>${t('Preview applies a temporary theme only in this tab. Save keeps a shared draft. Publish updates the whole website and portal.','ตัวอย่างแสดงธีมชั่วคราวในแท็บนี้ บันทึกเก็บร่างส่วนกลาง เผยแพร่เปลี่ยนทั้งเว็บไซต์และระบบการเรียน')}</p><form id="appearance-form"><div class="color-grid">${[['primary',t('Primary brand','สีแบรนด์หลัก')],['secondary',t('Secondary brand','สีแบรนด์รอง')],['accent',t('Accent','สีเน้น')],['background',t('Background','พื้นหลัง')],['text',t('Text','ข้อความ')]].map(([key,label])=>`<label>${label}<div class="color-control"><input aria-label="${label}" type="color" name="${key}" value="${a[key]}"><output>${a[key]}</output></div></label>`).join('')}</div><div id="contrast-warning" aria-live="polite">${contrastMessage(a)}</div><h3>${t('Logos & favicon','โลโก้และไอคอนเว็บไซต์')}</h3><p>${t('Transparent PNG or WebP works well for logos. Images retain their original proportions.','PNG หรือ WebP โปร่งใสเหมาะกับโลโก้ รูปภาพจะรักษาสัดส่วนเดิม')}</p><div class="two">${[['logo',t('Main logo','โลโก้หลัก')],['mobileLogo',t('Mobile logo (optional)','โลโก้มือถือ (ไม่บังคับ)')],['footerLogo',t('Footer logo (optional)','โลโก้ส่วนท้าย (ไม่บังคับ)')],['favicon',t('Favicon','ไอคอนเว็บไซต์')]].map(([key,label])=>`<div class="logo-setting"><label>${label}</label><div class="logo-preview">${a[key]?picture(a[key]):`<span>${t('Default Headstart mark','สัญลักษณ์ Headstart เริ่มต้น')}</span>`}</div><div class="inline-actions"><button type="button" data-pick-logo="${key}">${t('Choose from library','เลือกจากคลัง')}</button><button type="button" data-clear-logo="${key}">${t('Use default','ใช้ค่าเริ่มต้น')}</button></div></div>`).join('')}</div><div class="actions"><button type="button" class="button" id="brand-preview">${t('Preview on website','ดูตัวอย่างบนเว็บไซต์')}</button><button class="primary" ${session.role!=='admin'?'disabled':''}>${t('Save draft','บันทึกร่าง')}</button><button type="button" class="button green" id="brand-publish" ${session.role!=='admin'?'disabled':''}>${t('Publish changes','เผยแพร่การเปลี่ยนแปลง')}</button><button type="button" class="button" id="brand-cancel">${t('Cancel','ยกเลิก')}</button><button type="button" class="button" id="brand-defaults">${t('Restore defaults','คืนค่าเริ่มต้น')}</button></div><p>${t('Restore defaults changes the draft only until published.','คืนค่าเริ่มต้นเปลี่ยนเฉพาะร่างจนกว่าจะเผยแพร่')}</p></form></div>`}
function contrastMessage(a){const warnings=brandWarnings(a);return warnings.length?notice(t('Low contrast: ','ความเปรียบต่างต่ำ: ')+warnings.join(' · ')+t('. Aim for at least 4.5:1. Publishing is blocked until these combinations pass.',' ควรมีอย่างน้อย 4.5:1 ต้องแก้ไขก่อนเผยแพร่'),true):notice(t('Text combinations meet the 4.5:1 contrast target.','คู่สีข้อความผ่านเป้าหมายความเปรียบต่าง 4.5:1'))}
function editorPage(){draftContent??=structuredClone(site.content);const id=window.editContentId||'home',c={...DEFAULT_CONTENT[id],...draftContent[id]};return `${adminGate()}<div class="panel"><label>${t('Content to edit','เนื้อหาที่ต้องการแก้ไข')}<select id="content-select">${Object.keys(DEFAULT_CONTENT).map(k=>`<option value="${k}" ${k===id?'selected':''}>${esc(tx({...DEFAULT_CONTENT[k],...site.content[k]}.title))}</option>`).join('')}</select></label><form id="content-form"><div class="two"><section><h3>English · ${t('required fallback','ภาษาสำรองที่จำเป็น')}</h3>${field('title_en',t('Title','ชื่อเรื่อง'),c.title.en)}<label>${t('Description / lesson text','คำอธิบาย / เนื้อหาบทเรียน')}<textarea name="description_en" required maxlength="6000">${esc(c.description.en)}</textarea></label></section><section><h3>ไทย · ${t('optional','ไม่บังคับ')}</h3>${field('title_th',t('Thai title','ชื่อเรื่องภาษาไทย'),c.title.th||'','text',false)}<label>${t('Thai description / lesson text','คำอธิบาย / เนื้อหาบทเรียนภาษาไทย')}<textarea name="description_th" maxlength="6000">${esc(c.description.th||'')}</textarea></label></section></div>${c.type==='course'?`<label>${t('Teaching language (independent of interface)','ภาษาที่ใช้สอน (แยกจากภาษาเมนู)')}<select name="teaching">${['en','th','both'].map(code=>`<option value="${code}" ${c.language===code?'selected':''}>${languageName(code)}</option>`).join('')}</select></label>`:''}<label>${t('Image from public library','ภาพจากคลังสาธารณะ')}<select name="image"><option value="">${t('No custom image','ไม่มีภาพกำหนดเอง')}</option>${site.media.filter(m=>m.scope==='public').map(m=>`<option value="${m.id}" ${c.image===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>${notice(t('Empty Thai fields use the English text. Media and documents keep their original language.','ช่องภาษาไทยที่ว่างจะแสดงข้อความภาษาอังกฤษ สื่อและเอกสารยังคงภาษาต้นฉบับ'))}<div class="actions"><button type="button" class="button" id="content-preview">${t('Preview','ดูตัวอย่าง')}</button><button class="primary" ${session.role!=='admin'?'disabled':''}>${t('Save & publish content','บันทึกและเผยแพร่เนื้อหา')}</button><button type="button" class="button" id="content-cancel">${t('Cancel','ยกเลิก')}</button></div></form></div>`}
function mediaPage(){const allowed=['admin','teacher'].includes(session.role);return `${session.role==='admin'?adminGate():notice(allowed?t('Only images in your assigned courses can be managed here. Public and branding media require an administrator.','จัดการได้เฉพาะภาพในหลักสูตรที่ได้รับมอบหมาย สื่อสาธารณะและแบรนด์ต้องใช้สิทธิ์ผู้ดูแล'):t('Read-only preview. Sign in with an authorized administrator or assigned teacher account to upload.','ตัวอย่างแบบอ่านอย่างเดียว เข้าสู่ระบบด้วยบัญชีผู้ดูแลหรือครูที่ได้รับมอบหมายเพื่ออัปโหลด'),!allowed)}<div class="panel"><div class="heading-row"><h2>${t('Upload once. Use it again.','อัปโหลดครั้งเดียว ใช้ซ้ำได้')}</h2><span class="tag">JPEG · PNG · WebP</span></div><p>${t('Maximum 5 MB per image; 40 megapixels. Images are resized to 2400 px and optimized. Transparency is preserved.','ภาพละไม่เกิน 5 MB และ 40 ล้านพิกเซล ปรับขนาดสูงสุด 2400 พิกเซลและปรับไฟล์ให้เหมาะสม พร้อมรักษาความโปร่งใส')}</p><label>${t('Storage visibility','การเข้าถึงพื้นที่จัดเก็บ')}<select id="media-scope">${session.role!=='teacher'?`<option value="public">${t('Public website media','สื่อเว็บไซต์สาธารณะ')}</option>`:''}${(session.role==='teacher'?session.courses:['science','physics','chemistry']).map(c=>`<option value="course:${c}">${t('Private course','หลักสูตรส่วนตัว')}: ${esc(tx(content(c).title))}</option>`).join('')}</select></label><div id="dropzone" class="dropzone" tabindex="0" role="button" aria-label="${t('Select or drop images','เลือกหรือลากภาพมาวาง')}" aria-disabled="${!allowed}"><strong>${t('Drop images here','ลากภาพมาวางที่นี่')}</strong><span>${t('or choose files','หรือเลือกไฟล์')}</span><input id="media-files" aria-label="${t('Choose images','เลือกภาพ')}" type="file" accept="image/jpeg,image/png,image/webp" multiple ${!allowed?'disabled':''}></div><div id="upload-state" role="status"></div></div><div class="heading-row"><h2>${t('Your media library','คลังสื่อของคุณ')}</h2><label>${t('Filter','กรอง')}<select id="media-filter"><option value="all">${t('All permitted images','ภาพทั้งหมดที่มีสิทธิ์')}</option><option value="public">${t('Public','สาธารณะ')}</option><option value="private">${t('Private course images','ภาพหลักสูตรส่วนตัว')}</option></select></label></div><div class="grid media-grid" id="media-grid">${mediaCards(site.media)}</div>`}
function mediaCards(list){return list.map(m=>`<article class="card"><button class="media-thumb" data-edit-media="${m.id}">${picture(m.id)}</button><div class="card-body"><strong>${esc(m.name)}</strong><p>${m.width} × ${m.height} · ${Math.round(m.size/1024)} KB</p><span class="tag ${m.scope==='public'?'':'gray'}">${m.scope==='public'?t('Public','สาธารณะ'):t('Private','ส่วนตัว')}</span><p>${esc(tx(m.alt))||t('Alt text needed','ต้องเพิ่มข้อความทดแทน')}</p><button class="button small" data-edit-media="${m.id}">${t('Edit / reuse','แก้ไข / ใช้ซ้ำ')}</button></div></article>`).join('')||empty(t('No images yet','ยังไม่มีภาพ'),t('Upload an image to preview it, add bilingual text, and reuse it across the website.','อัปโหลดภาพเพื่อดูตัวอย่าง เพิ่มข้อความสองภาษา และใช้ซ้ำในเว็บไซต์'))}
function editMedia(id){const m=media(id);if(!m)return;selectedMedia=id;const refs=usage(id);modal(`<h2>${t('Image details','รายละเอียดภาพ')}</h2><div class="focal-preview">${picture(id)}</div><form id="media-edit"><div class="two">${field('alt_en',t('Alternative text · English','ข้อความทดแทน · อังกฤษ'),m.alt.en)}${field('alt_th',t('Alternative text · Thai','ข้อความทดแทน · ไทย'),m.alt.th,'text',false)}${field('caption_en',t('Caption · English','คำบรรยาย · อังกฤษ'),m.caption.en,'text',false)}${field('caption_th',t('Caption · Thai','คำบรรยาย · ไทย'),m.caption.th,'text',false)}</div><div class="two"><label>${t('Focal point · horizontal','จุดโฟกัส · แนวนอน')}<input name="x" type="range" min="0" max="100" value="${m.focal.x}"></label><label>${t('Focal point · vertical','จุดโฟกัส · แนวตั้ง')}<input name="y" type="range" min="0" max="100" value="${m.focal.y}"></label></div><p>${t('Focal point controls how banners and thumbnails crop this image.','จุดโฟกัสกำหนดการครอบตัดภาพแบนเนอร์และภาพย่อ')}</p><button class="primary">${t('Save image details','บันทึกรายละเอียดภาพ')}</button></form><h3 style="margin-top:25px">${t('Used in','ใช้ใน')}</h3><p>${refs.map(esc).join(', ')||t('Not currently used','ยังไม่ถูกใช้งาน')}</p><label>${t('Replace image (keeps existing placements)','แทนที่ภาพ (คงตำแหน่งการใช้งานเดิม)')}<input id="replace-image" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="inline-actions">${m.scope==='public'?`<button id="reuse-image">${t('Use in content','ใช้ในเนื้อหา')}</button>`:''}<button id="delete-image">${t('Delete image','ลบภาพ')}</button></div><div id="media-action-status" role="status"></div>`);$('#media-edit').onsubmit=async e=>{e.preventDefault();if(!validateForm(e.target))return;const f=new FormData(e.target);await saveAction(async()=>{await api('/api/media/'+id,{method:'PATCH',body:JSON.stringify({alt:pair(f.get('alt_en'),f.get('alt_th')),caption:pair(f.get('caption_en'),f.get('caption_th')),focal:{x:+f.get('x'),y:+f.get('y')}})});$('#modal').close();await loadSite();render();toast('Image details saved.','บันทึกรายละเอียดภาพแล้ว')})};$('#media-edit').oninput=e=>{if(['x','y'].includes(e.target.name))$('.focal-preview img').style.objectPosition=`${$('#media-edit [name=x]').value}% ${$('#media-edit [name=y]').value}%`};$('#replace-image').onchange=e=>uploadFiles(e.target.files,id);if($('#reuse-image'))$('#reuse-image').onclick=()=>{$('#modal').close();window.editContentId='home';draftContent??=structuredClone(site.content);draftContent.home.image=id;location.hash='portal/content';render()};$('#delete-image').onclick=()=>{const current=usage(id);if(current.length){$('#media-action-status').innerHTML=notice(t('Replace or remove this image in these published or draft locations before deleting: ','ก่อนลบ ต้องแทนที่หรือนำภาพออกจากตำแหน่งที่เผยแพร่หรือร่างเหล่านี้: ')+current.map(esc).join(', '),true);return}$('#media-action-status').innerHTML=`<p>${t('Delete this unused image permanently?','ลบภาพที่ไม่ถูกใช้งานนี้อย่างถาวรหรือไม่?')}</p><button class="button" id="confirm-delete">${t('Confirm delete','ยืนยันการลบ')}</button>`;$('#confirm-delete').onclick=()=>saveAction(async()=>{await api('/api/media/'+id,{method:'DELETE'});$('#modal').close();await loadSite();render();toast('Image deleted.','ลบภาพแล้ว')})}}
function usage(id){const refs=[];for(const [k,c]of Object.entries(site.content))if(c.image===id)refs.push(tx(c.title)||k);for(const [k,v]of Object.entries(site.appearance))if(v===id)refs.push(t('Published branding: ','แบรนด์ที่เผยแพร่: ')+k);for(const [k,v]of Object.entries(site.draftAppearance||{}))if(v===id)refs.push(t('Draft branding: ','แบรนด์ฉบับร่าง: ')+k);return refs}
function statusPage(){return `<div class="container">${heading(t('System status','สถานะระบบ'),t('What is connected','สิ่งที่เชื่อมต่อแล้ว'))}<div class="two"><div class="panel"><h2>${t('Website management','การจัดการเว็บไซต์')}</h2><p>${online?t('Connected to server-backed storage. Authorized accounts can save bilingual content, publish branding, and manage media.','เชื่อมต่อที่เก็บข้อมูลบนเซิร์ฟเวอร์ บัญชีที่ได้รับอนุญาตบันทึกเนื้อหาสองภาษา เผยแพร่แบรนด์ และจัดการสื่อได้'):t('Local preview only. Shared storage is not connected at this address.','ตัวอย่างในเครื่องเท่านั้น ที่อยู่นี้ไม่เชื่อมต่อพื้นที่จัดเก็บส่วนกลาง')}</p><p>${t('EN / TH preference is remembered on this device. English is the default and the fallback for missing Thai content.','จำภาษา EN / TH บนอุปกรณ์นี้ อังกฤษเป็นค่าเริ่มต้นและภาษาสำรองเมื่อไม่มีเนื้อหาไทย')}</p></div><div class="panel"><h2>${t('LMS remains a prototype','ระบบการเรียนยังเป็นต้นแบบ')}</h2><p>${t('Student accounts, email/password sign-in, private video playback, real exams, certificates, email and LINE delivery are not connected. Demo data resets on reload.','บัญชีนักเรียน การเข้าสู่ระบบด้วยอีเมลและรหัสผ่าน วิดีโอส่วนตัว การสอบจริง ใบประกาศ อีเมลและ LINE ยังไม่เชื่อมต่อ ข้อมูลสาธิตรีเซ็ตเมื่อโหลดใหม่')}</p><p>${t('School-approved content and the reference PDF have not been supplied.','ยังไม่ได้รับเนื้อหาที่โรงเรียนอนุมัติและไฟล์ PDF อ้างอิง')}</p></div></div></div>`}
async function api(path,options={}){const headers={...options.headers};if(options.body&&!(options.body instanceof Blob)&&!(options.body instanceof FormData))headers['Content-Type']='application/json';const res=await fetch(path,{...options,headers});let body;try{body=await res.json()}catch{throw new Error('unavailable')}if(!res.ok)throw new Error(body.error||'unavailable');return body}
function errorText(code){return ({forbidden:t('Your account is not authorized for this action.','บัญชีของคุณไม่ได้รับอนุญาตให้ทำรายการนี้'),conflict:t('Someone updated the site. Reload the latest data before trying again. Your current form is preserved.','มีผู้แก้ไขเว็บไซต์แล้ว โหลดข้อมูลล่าสุดก่อนลองอีกครั้ง แบบฟอร์มปัจจุบันยังคงอยู่'),in_use:t('This image is in use. Replace it in all content and branding before deleting.','ภาพนี้ถูกใช้งานอยู่ ต้องแทนที่ในเนื้อหาและแบรนด์ก่อนลบ'),invalid_image:t('Choose a valid JPEG, PNG, or WebP image, maximum 5 MB.','เลือก JPEG, PNG หรือ WebP ที่ถูกต้อง ไม่เกิน 5 MB'),contrast:t('Please fix the low-contrast colors before publishing.','โปรดแก้คู่สีที่ความเปรียบต่างต่ำก่อนเผยแพร่'),invalid:t('Check the form values and try again.','ตรวจสอบข้อมูลในแบบฟอร์มแล้วลองใหม่'),unavailable:t('The server is unavailable. Your form has been preserved; try again later.','เซิร์ฟเวอร์ไม่พร้อมใช้งาน เก็บข้อมูลในแบบฟอร์มไว้แล้ว โปรดลองภายหลัง')})[code]||t('Unable to save. Your form is preserved. Please try again.','บันทึกไม่สำเร็จ ข้อมูลในแบบฟอร์มยังอยู่ โปรดลองอีกครั้ง')}
async function saveAction(fn){try{await fn()}catch(e){toast(errorText(e.message));return false}return true}
async function loadSite(){try{const [publicData,me]=await Promise.all([api('/api/site'),api('/api/session')]);online=true;session=me;site={...site,...publicData,content:{...structuredClone(DEFAULT_CONTENT),...publicData.content}};if(['admin','teacher'].includes(me.role)){const d=await api('/api/manage');etag=d.etag;site={...site,...d,content:{...structuredClone(DEFAULT_CONTENT),...d.content}}}applyAppearance(site.appearance)}catch{online=false}}
async function saveSite(changes){const result=await api('/api/site',{method:'PUT',body:JSON.stringify({etag,...changes})});etag=result.etag;await loadSite()}
function readAppearance(){const f=$('#appearance-form');if(f)for(const k of ['primary','secondary','accent','background','text'])draftAppearance[k]=f.elements[k].value;return draftAppearance}
function readContent(){const f=$('#content-form'),id=window.editContentId||'home';if(!f)return;const d=new FormData(f),c={...DEFAULT_CONTENT[id],...draftContent[id],title:pair(d.get('title_en'),d.get('title_th')),description:pair(d.get('description_en'),d.get('description_th')),image:d.get('image')||null};if(c.type==='course')c.language=d.get('teaching');draftContent[id]=c;return c}
function applyAppearance(a){a={...DEFAULT_APPEARANCE,...a};const root=document.documentElement;for(const [key,value]of Object.entries({'--brand-primary':a.primary,'--navy':a.primary,'--muted':a.secondary,'--green':a.accent,'--white':a.background,'--page-bg':a.background,'--text':a.text,'--paper':a.background,'--on-primary':contrast(a.primary,'#ffffff')>=contrast(a.primary,'#000000')?'#ffffff':'#000000'}))root.style.setProperty(key,value);document.querySelectorAll('.brand').forEach((b,i)=>{const id=i?a.footerLogo||a.logo:(innerWidth<700?a.mobileLogo||a.logo:a.logo);b.innerHTML=id&&media(id)?picture(id,'','brand-image'):'<b class="logo">H<span>↗</span></b><span>Headstart<small>ACADEMICS</small></span>'});const favicon=$('link[rel=icon]');favicon.href=a.favicon&&media(a.favicon)?`/api/media/${a.favicon}?v=${media(a.favicon).version}`:defaultFavicon}
const defaultFavicon=$('link[rel=icon]').href;
function updateShell(){document.documentElement.lang=lang;$('.skip').textContent=t('Skip to content','ข้ามไปยังเนื้อหา');$('.mobile-menu').setAttribute('aria-label',t('Open navigation','เปิดเมนู'));$('nav').setAttribute('aria-label',t('Main navigation','เมนูหลัก'));$('nav').innerHTML=[['home',t('Home','หน้าแรก')],['about',t('About us','รู้จักเรา')],['courses',t('Courses','หลักสูตร')],['resources',t('Free resources','เรียนรู้ฟรี')],['events',t('Events','กิจกรรม')],['contact',t('Contact','ติดต่อเรา')],['login',t('My learning','พื้นที่การเรียนรู้')]].map(([id,label])=>`<a href="#${id}" class="${route()[0]===id?'active':''}">${label}</a>`).join('');$('.signin').textContent=t('My learning ↗','พื้นที่การเรียนรู้ ↗');$('.signin').href=demo.role?'#portal/overview':'#login';$('.demo-bar').innerHTML=`${t('HEADSTART / LEARNING PROTOTYPE','HEADSTART / ต้นแบบการเรียนรู้')}<span>${t('Sample courses and student data','หลักสูตรและข้อมูลนักเรียนตัวอย่าง')}</span><a href="#status">${t('System status','สถานะระบบ')} ↗</a>`;$('footer p').textContent=t('A place for questions. A world of discoveries.','พื้นที่ของคำถามและการค้นพบ');$('footer div').innerHTML=`<a href="#about">${t('About us','รู้จักเรา')}</a><a href="#contact">${t('Contact','ติดต่อเรา')}</a><a href="#status">${t('System status','สถานะระบบ')}</a>`;$('footer > small').textContent=t('© Headstart Academics · English / ไทย','© Headstart Academics · English / ไทย');$('.close').setAttribute('aria-label',t('Close','ปิด'));$('#language-switch').innerHTML=['en','th'].map(l=>`<button type="button" data-lang="${l}" aria-pressed="${l===lang}" lang="${l}">${l.toUpperCase()}</button>`).join('');document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>switchLanguage(b.dataset.lang));applyAppearance(previewing?draftAppearance:site.appearance)}
function switchLanguage(next){if(next===lang)return;const focus=document.activeElement?.name;const values=[...main.querySelectorAll('input:not([type=file]),textarea,select')].map((e,i)=>({i,name:e.name,id:e.id,value:e.value,checked:e.checked,type:e.type}));if($('#appearance-form'))readAppearance();if($('#content-form'))readContent();const scroll=window.scrollY;lang=next;try{localStorage.setItem('hs-language',lang)}catch{}if($('#modal').open)$('#modal').close();render();values.forEach(v=>{const el=v.id?document.getElementById(v.id):v.name?main.querySelector(`[name="${v.name}"]`):null;if(el&&el.type===v.type){el.value=v.value;el.checked=v.checked}});if(focus)main.querySelector(`[name="${focus}"]`)?.focus();window.scrollTo(0,scroll)}
function route(){return (location.hash.slice(1)||'home').split('/')}
function render(){const [p,id]=route();updateShell();const pages={home,courses:catalog,about,resources,article:()=>article(id),lab,events:eventsPage,contact,login,register,course:()=>course(id),portal:()=>portal(id),status:statusPage,reset:()=>`<div class="container narrow">${heading(t('Password reset','รีเซ็ตรหัสผ่าน'),t('School accounts are not connected yet','ยังไม่เชื่อมต่อบัญชีโรงเรียน'))}${notice(t('No password-reset email can be sent in this prototype. Website administrators use ChatGPT sign-in.','ต้นแบบนี้ไม่ส่งอีเมลรีเซ็ตรหัสผ่าน ผู้ดูแลเว็บไซต์ใช้การเข้าสู่ระบบด้วย ChatGPT'))}</div>`};main.innerHTML=(pages[p]||notFound)();document.title=`${t('Headstart Academics · Learn & discover','Headstart Academics · เรียนรู้และค้นพบ')}`;$('nav').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');$('#preview-banner').hidden=!previewing;$('#preview-banner').innerHTML=previewing?`${t('Appearance preview — not published','ตัวอย่างรูปลักษณ์ — ยังไม่เผยแพร่')} <button id="end-preview">${t('Exit preview','ออกจากตัวอย่าง')}</button>`:'';if($('#end-preview'))$('#end-preview').onclick=()=>{previewing=false;applyAppearance(site.appearance);render()};bind();installValidation()}
function validateForm(form){for(const el of form.elements){if(!el.willValidate)continue;el.setCustomValidity('');if(!el.validity.valid){el.setCustomValidity(el.validity.valueMissing?t('Please complete this field.','กรุณากรอกข้อมูลช่องนี้'):el.validity.typeMismatch?t('Enter a valid email address.','กรุณากรอกอีเมลที่ถูกต้อง'):t('Please check this value.','กรุณาตรวจสอบค่านี้'));el.reportValidity();return false}}return true}
function installValidation(){document.querySelectorAll('form').forEach(f=>{f.noValidate=true;f.addEventListener('submit',e=>{if(!validateForm(f)){e.preventDefault();e.stopImmediatePropagation()}},true);f.addEventListener('input',e=>e.target.setCustomValidity?.(''))})}
