if($('#search')){const filter=()=>{const q=$('#search').value.toLowerCase(),s=$('#subject').value,l=$('#level').value,ids=courseIds.filter(id=>(!s||s===id)&&(!l||l===id)&&JSON.stringify(content(id)).toLowerCase().includes(q));$('#course-results').innerHTML=ids.map(id=>card(id)).join('')||empty(t('No matching courses','ไม่พบหลักสูตรที่ตรงกัน'),t('Try another search or level.','ลองคำค้นหาหรือระดับชั้นอื่น'));$('#result-count').textContent=ids.length+' '+t('sample courses','หลักสูตรตัวอย่าง')};['search','subject','level'].forEach(id=>$('#'+id).oninput=filter);filter()}
